// ─── HELPER per moduli compatti ──────────────────────────────────────────────
function buildModules(courseId, courseTitle, rawModules) {
  return rawModules.map((m, i) => ({
    id: `c${courseId}_${String(i + 1).padStart(2, "0")}`,
    courseId,
    index: i,
    title: m.t,
    duration: m.dur || 13,
    youtube: null,
    hero: { headline: m.t, stat: m.stat || "", context: `${courseTitle} — Modulo ${i + 1} di 20` },
    objectives: m.obj || ["Analizzare il tema", "Applicare le tecniche", "Costruire la strategia", "Misurare i risultati"],
    context: m.ctx || `${courseTitle} — modulo ${i + 1}`,
    slides: m.slides || Array.from({ length: 8 }, (_, s) => ({ title: `Sezione ${s + 1}`, body: `${m.t} — sezione ${s + 1}.` })),
    mapSvg: `<svg viewBox="0 0 400 180" xmlns="http://www.w3.org/2000/svg"><rect width="400" height="180" fill="#0b1220"/><text x="200" y="90" textAnchor="middle" fill="#C9A227" fontSize="14" fontFamily="serif">${courseTitle}</text><text x="200" y="115" textAnchor="middle" fill="#ffffff88" fontSize="10">Modulo ${i + 1}</text></svg>`,
    deepDive: m.dd || `Modulo ${i + 1}: ${m.t}. Approfondimento professionale.`,
    caseStudies: m.cs || [],
    techniques: m.tech || [],
    exercise: m.ex || { title: `Esercizio Modulo ${i + 1}`, steps: ["Analizzare il caso", "Applicare il framework", "Documentare i risultati"] },
    keyPoints: m.kp || [`Punto chiave 1 del modulo ${i + 1}`, `Punto chiave 2`, `Punto chiave 3`],
    quiz: m.quiz || Array.from({ length: 5 }, (_, q) => ({ q: `Domanda ${q + 1}`, options: ["A", "B", "C", "D"], correct: q % 4 })),
  }));
}

const compact = (courseId, title, titles20) =>
  buildModules(courseId, title, titles20.map(t => ({ t })));

// ─── CORSO 15: Tax e Legale ──────────────────────────────────────────────────
export const TAX_LEGALE_MODULES = buildModules(15, "Tax e Legale", [
  { t: "Il Quadro Fiscale del Fine Wine in Italia", ctx: "Come il sistema fiscale italiano tratta il fine wine: capital gain, IVA, dichiarazione dei redditi.", dd: "In Italia, il fine wine è classificato come bene mobile non produttivo di reddito se detenuto per uso personale. Le plusvalenze da vendita sono soggette a imposta del 26% (capital gain su beni mobili). Tuttavia, se il vino è acquistato per investimento e venduto con frequenza, l'attività potrebbe essere qualificata come commerciale, con aliquota IRPEF progressiva. Strategia ottimale: documentare l'acquisto come collezionismo, limitare le vendite annuali.", quiz: [{q:"L'aliquota capital gain su beni mobili in Italia è:",o:["12.5%","19%","26%","43%"],c:2},{q:"Il fine wine in Italia è classificato come:",o:["Attività finanziaria","Bene mobile non produttivo di reddito (uso personale)","Immobile","Derivato finanziario"],c:1},{q:"Quando l'attività di vendita vino diventa 'commerciale':",o:["Sempre","Quando si vende con frequenza e per profitto sistematico","Solo sopra €100k/anno","Mai"],c:1},{q:"La strategia fiscale ottimale è:",o:["Vendere tutto entro l'anno","Documentare come collezionismo e limitare vendite annuali","Non dichiarare","Aprire una SRL"],c:1},{q:"L'IVA sul vino acquistato per investimento è:",o:["Non detraibile (uso personale)","Detraibile al 100%","Detraibile al 50%","Non applicabile"],c:0}] },
  { t: "Fiscalità Internazionale: UK, USA, Francia", ctx: "Come i principali paesi del fine wine trattano il capital gain: il vantaggio del UK per gli investitori.", dd: "Il UK offre il trattamento fiscale più favorevole: il fine wine è classificato come 'wasting asset' (vita utile < 50 anni) ed è quindi esente da Capital Gains Tax. Questa è la ragione principale per cui London è il hub globale del fine wine investing. USA: collectibles CGT del 28%. Francia: exonération se detenuto > 2 anni e vendita < €5.000 (altrimenti 36.2% con CSG). Per investitori internazionali, la struttura fiscale ottimale è attraverso una holding UK o Irish entity.", quiz: [{q:"Il UK tassa il capital gain sul fine wine?",o:["Sì, 20% flat","Sì, 28% (collectibles)","No — è esente come wasting asset","Sì, 40% per higher rate taxpayers"],c:2},{q:"La classificazione 'wasting asset' nel UK richiede:",o:["Il vino sia di bassa qualità","La vita utile prevista < 50 anni","Il valore sia < £5.000","Il vino sia acquistato all'asta"],c:1},{q:"L'aliquota CGT USA per i collectibles (incluso fine wine) è:",o:["15%","20%","28%","35%"],c:2},{q:"La struttura ottimale per un investitore internazionale è:",o:["Acquistare in Italia","Holding UK o Irish entity","Trust svizzero","LLC americana"],c:1},{q:"In Francia, la vendita è esente se:",o:["Sempre esente","Detenuto > 2 anni E vendita < €5.000","Solo per Bordeaux","Detenuto > 10 anni"],c:1}] },
  ...Array.from({length:18}, (_,i) => ({ t: ["IVA e Accise: Import/Export di Fine Wine","Strutturare un'Eredità di Vino","Trust e Società per la Detenzione di Wine Assets","Insurance: Valutazione e Copertura Corretta","Assicurazione per Trasporti Internazionali","Due Diligence Legale Prima dell'Acquisto","Contratti di Vendita Privata: Clausole Chiave","Dispute Resolution nel Fine Wine","La Normativa Wine Merchant in Europa","GDPR e Privacy per Merchant e Collector","Anti-Money Laundering (AML) nel Fine Wine","Importare Vino Extra-UE: Dazi e Procedure","Esportare Fine Wine: Documentazione Richiesta","NFT e Tokenizzazione del Vino: Aspetti Legali","La Regolamentazione delle Auction House","Fraud Prevention: Tutele Legali dell'Acquirente","Pianificazione Patrimoniale con Fine Wine","Certificazione Tax & Legal Specialist"][i], ctx: `Modulo ${i+3} tax e legale`, dd: `Approfondimento fiscale e legale — modulo ${i+3}.`, quiz: Array.from({length:5},(_,q)=>({q:`Domanda ${q+1}`,options:["A","B","C","D"],correct:q%4})) })),
]);

